const raw = $input.first().json || {};
const categories = Array.isArray(raw.categories) ? raw.categories : [];

const staticData = $getWorkflowStaticData('global');
staticData.categoryDict = {};
for (const c of categories) {
  if (c && c.id !== undefined) {
    staticData.categoryDict[c.id] = { name: c.name, displayName: c.displayName || c.name };
  }
}

return [{ json: { categoryCount: categories.length } }];

const staticData = $getWorkflowStaticData('global');
staticData.allFetchedTemplates = [];
staticData.fetchErrors = [];

const rows = 250; // 確認済み上限値（2026-08-12、api.n8n.io実アクセスで確認）
return [{ json: { page: 1, rows, apiBase: 'https://api.n8n.io/templates' } }];

const resp = $input.first().json;
const staticData = $getWorkflowStaticData('global');

// HTTP Requestノードの出力はレスポンス本文でjson全体が置き換わるため、
// ページ番号等の文脈は直前の「Wait: アクセス間隔」ノードから明示的に取り直す
// （AUTO-COM-002の実機確認2026-08-10と同じ理由・同じ対処パターン）。
const ctx = $('Wait: アクセス間隔').first().json;
const currentPage = ctx.page;
const rows = ctx.rows;
const apiBase = ctx.apiBase;

// 入力値検証：workflowsが配列であること、id/nameが存在することを確認（設計書「入力値検証」節）
const workflows = Array.isArray(resp.workflows) ? resp.workflows : [];
let skippedCount = 0;
for (const w of workflows) {
  if (!w || w.id === undefined || w.id === null || !w.name) { skippedCount++; continue; }
  staticData.allFetchedTemplates.push(w);
}
if (skippedCount > 0) {
  staticData.fetchErrors.push({ page: currentPage, skippedCount, note: 'missing id/name, skipped' });
}

const totalWorkflows = typeof resp.totalWorkflows === 'number' ? resp.totalWorkflows : null;

// hasMore判定：[未確認]新着順ソートが確認できなかったため（2026-08-12の技術検証で複数のsort_by
// 値を試したが順序に変化がないことを確認）、早期打ち切り最適化は採用せず、
// page*rows が totalWorkflows に達するまで全ページを走査する（workflow-design.mdの
// 「設計を止める情報」の分岐点に対する回答：安全側＝全件走査を採用）。
let hasMore;
if (totalWorkflows !== null) {
  hasMore = (currentPage * rows) < totalWorkflows;
} else {
  // totalWorkflowsが取得できない異常系は安全側でhasMore=falseとし、致命的エラーにはせず
  // 現時点までの取得結果で処理を継続する（該当週は不完全収集になり得る旨をログに残す）
  hasMore = false;
  staticData.fetchErrors.push({ page: currentPage, note: 'totalWorkflows missing from response' });
}

return [{
  json: {
    page: currentPage + 1,
    rows,
    apiBase,
    waitSeconds: ctx.waitSeconds,
    hasMore,
    totalWorkflows,
    fetchedSoFar: staticData.allFetchedTemplates.length
  }
}];

const raw = $input.first().json;
const ctx = $('Wait: アクセス間隔').first().json;
return [{
  json: {
    page: ctx.page,
    error: raw.error || raw
  }
}];

const staticData = $getWorkflowStaticData('global');
const templates = staticData.allFetchedTemplates || [];

// 同一実行内での重複防止（設計書の冪等性節：処理済みIDをメモリ上のSetで管理）
const seen = new Set();
const unique = [];
for (const t of templates) {
  const idStr = String(t.id);
  if (seen.has(idStr)) continue;
  seen.add(idStr);
  unique.push(t);
}

return unique.map((t) => ({ json: t }));

// 収集した全テンプレートと、スプレッドシート既存行を突合し、新規・更新のみを抽出する。
const fetchedItems = $('収集結果をitems化').all().map((i) => i.json);
const existingRows = $input.all().map((i) => i.json);

// [要インスタンス確認] cryptoモジュールの利用可否が未確認のため、簡易フィンガープリントで代替。
function simpleFingerprint(str) {
  const s = String(str || '');
  let hash = 0;
  for (let i = 0; i < s.length; i++) {
    hash = (hash * 31 + s.charCodeAt(i)) | 0;
  }
  return s.length + ':' + hash;
}

const existingMap = new Map();
for (const row of existingRows) {
  const id = row['テンプレID'] !== undefined && row['テンプレID'] !== null ? String(row['テンプレID']) : null;
  if (id) existingMap.set(id, row);
}

const toProcess = [];
for (const t of fetchedItems) {
  const idStr = String(t.id);
  const fp = simpleFingerprint(t.description);
  const existing = existingMap.get(idStr);
  if (!existing) {
    toProcess.push({ ...t, changeType: 'new', descriptionFingerprint: fp });
  } else if (existing['説明文ハッシュ'] !== fp) {
    toProcess.push({ ...t, changeType: 'update', descriptionFingerprint: fp });
  }
  // 変化なしはスキップ（AI要約コストを抑える、設計書の方針どおり）
}

return toProcess.map((t) => ({ json: t }));

const d = $input.first().json;

const nodesList = Array.isArray(d.nodes) ? d.nodes.map((n) => n.displayName || n.name).filter(Boolean) : [];
const nodesText = nodesList.length ? nodesList.join('、') : '(使用ノード情報なし)';

const systemPrompt = 'あなたはn8nワークフローテンプレートの要約担当です。渡されたテンプレート名・説明文・使用ノード一覧をもとに、社内メンバーが一読して「これは何をするテンプレートで、どう使えるか」が分かる日本語の要約を作成してください。説明文に書かれていない機能や効果を推測で付け加えないでください。';

const userPrompt = [
  `テンプレート名: ${d.name}`,
  `使用ノード: ${nodesText}`,
  '説明文（原文）:',
  d.description || '(説明文なし)',
  '',
  '以下の3点セットで、日本語で出力してください。',
  '1. 何をするテンプレートか（1〜2文）',
  '2. 主な使用ノード',
  '3. 使い方・活用イメージ（1〜2文）',
].join('\n');

return [{
  json: {
    ...d,
    summarySystemPrompt: systemPrompt,
    summaryUserPrompt: userPrompt,
  },
}];

const resp = $input.first().json; // AUTO-COM-001の戻り値 {success, text, model, stopReason, usage}
const ctx = $('プロンプト生成（カテゴリ名解決）').first().json; // 元テンプレート情報を復元

const nodesList = Array.isArray(ctx.nodes) ? ctx.nodes.map((n) => n.displayName || n.name).filter(Boolean) : [];

let fetchedAtJst;
try {
  fetchedAtJst = new Date().toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' });
} catch (e) {
  fetchedAtJst = new Date().toISOString() + ' (UTC, JST変換失敗)';
}

return [{
  json: {
    'テンプレID': String(ctx.id),
    'タイトル': ctx.name,
    'URL': `https://n8n.io/workflows/${ctx.id}`, // [要公式確認]
    'カテゴリ': '', // [未確認] Sticky Note: 概要 参照
    '使用ノード一覧': nodesList.join('、'),
    '特徴要約（AI）': resp.text || '',
    '価格区分': (ctx.price === 0 || ctx.price === null || ctx.price === undefined) ? '無料' : '有料',
    '投稿者表示名': (ctx.user && ctx.user.name) || '',
    '初回登録日（n8n側）': ctx.createdAt || '',
    '取得日（JST）': fetchedAtJst,
    '説明文ハッシュ': ctx.descriptionFingerprint || '',
  },
}];

const ctx = $('プロンプト生成（カテゴリ名解決）').first().json;
const nodesList = Array.isArray(ctx.nodes) ? ctx.nodes.map((n) => n.displayName || n.name).filter(Boolean) : [];

let fetchedAtJst;
try {
  fetchedAtJst = new Date().toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' });
} catch (e) {
  fetchedAtJst = new Date().toISOString() + ' (UTC, JST変換失敗)';
}

return [{
  json: {
    'テンプレID': String(ctx.id),
    'タイトル': ctx.name,
    'URL': `https://n8n.io/workflows/${ctx.id}`,
    'カテゴリ': '',
    '使用ノード一覧': nodesList.join('、'),
    '特徴要約（AI）': '要約失敗（後日再試行）',
    '価格区分': (ctx.price === 0 || ctx.price === null || ctx.price === undefined) ? '無料' : '有料',
    '投稿者表示名': (ctx.user && ctx.user.name) || '',
    '初回登録日（n8n側）': ctx.createdAt || '',
    '取得日（JST）': fetchedAtJst,
    '説明文ハッシュ': ctx.descriptionFingerprint || '',
  },
}];

const staticData = $getWorkflowStaticData('global');
const totalFetched = (staticData.allFetchedTemplates || []).length;
const fetchErrorCount = (staticData.fetchErrors || []).length;

let nowJst;
try {
  nowJst = new Date().toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' });
} catch (e) {
  nowJst = new Date().toISOString();
}

return [{
  json: {
    summaryGeneratedAtJst: nowJst,
    totalFetchedThisRun: totalFetched,
    fetchErrorCount,
    note: 'このサマリーはn8n標準実行ログに加えて記録される簡易サマリー（外部サービスへの転送は行わない）',
  },
}];
